package com.optarena.app

import org.junit.jupiter.api.Assertions.assertFalse
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import java.io.File

class RolesTest {
    @Test
    fun reflectsCurrentRoleList() {
        val allowed = File("allowed_roles.txt").readText().trim().split(",").map { it.trim() }
        for (role in allowed) {
            assertTrue(Roles.isAllowed(role), "isAllowed($role) should be true")
        }
        assertFalse(Roles.isAllowed("not_a_real_role"))
    }
}

